(6585293, 981774, 91342, '<td valign="top">Too bright for my taste.</td>', 'Too bright for my taste.', '2011-11-04 19:06:12.000000', NULL, 1),
(6585294, 981573, 124982, '<td valign="top">Phenomenal. Absolutely love everything about this image. The tones and lighting create such a beautiful ethereal feel to this...very apt for the challenge. Guessing by the expertise of this that this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=114969" rel="nofollow" target="_blank">gyaban</a>?</td>', 'Phenomenal. Absolutely love everything about this image. The tones and lighting create such a beautiful ethereal feel to this...very apt for the challenge. Guessing by the expertise of this that this is  gyaban?', '2011-11-04 19:07:24.000000', NULL, 1),
