(6586037, 981202, 62249, '<td valign="top">Composition is okay. Lighting isn''t very interesting. Need more detail on either cat whiskers or chest fur. Focus on eyes isn''t quite sharp.</td>', 'Composition is okay. Lighting isn''t very interesting. Need more detail on either cat whiskers or chest fur. Focus on eyes isn''t quite sharp.', '2011-11-05 18:41:45.000000', NULL, 1),
(6586038, 982180, 62249, '<td valign="top">Looks too contemporary for the genre. Bright nose and dot between eyes are distracting.</td>', 'Looks too contemporary for the genre. Bright nose and dot between eyes are distracting.', '2011-11-05 18:41:48.000000', NULL, 1),
(6586039, 982211, 62249, '<td valign="top">It''s a pretty woodland scene, but you haven''t pushed it enough to seem like a Poe scenario. In Expert Editing, you''ve got a LOT of leeway in what you can do with the image.</td>', 'It''s a pretty woodland scene, but you haven''t pushed it enough to seem like a Poe scenario. In Expert Editing, you''ve got a LOT of leeway in what you can do with the image.', '2011-11-05 18:41:51.000000', NULL, 1),
