INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6586668, 981539, 124982, '<td valign="top">What a mind trip!!</td>', 'What a mind trip!!', '2011-11-06 18:18:19.000000', NULL, 1),
(6586670, 982224, 124982, '<td valign="top">Quite simple, but beautifully done. Gorgeous model and wonderfully processed with the grain/texture. Top 10.</td>', 'Quite simple, but beautifully done. Gorgeous model and wonderfully processed with the grain/texture. Top 10.', '2011-11-06 18:19:18.000000', NULL, 1),
(6586675, 981566, 124982, '<td valign="top">Upping my previous vote. Very well done. love the lips and the eyes. The lighting is a little too "cheerful" for the topic though...something moodier may have suited better? Just thinking out loud, never took points off.</td>', 'Upping my previous vote. Very well done. love the lips and the eyes. The lighting is a little too "cheerful" for the topic though...something moodier may have suited better? Just thinking out loud, never took points off.', '2011-11-06 18:21:24.000000', NULL, 1),
(6586724, 982004, 133346, '<td valign="top">Hey!!!!This is the coolest picture I have seen!!!!</td>', 'Hey!!!!This is the coolest picture I have seen!!!!', '2011-11-06 19:16:46.000000', NULL, 1),
(6586727, 982127, 133346, '<td valign="top">Brilliant!!!!</td>', 'Brilliant!!!!', '2011-11-06 19:19:55.000000', NULL, 1),
(6586873, 982127, 43463, '<td valign="top">Upon my true face revealed<br/>Foolish Revelers fates are sealed<br/>Silent is my scream for I need no voice<br/>Grave tidings  is the scarlet ''gift'' I foist<br/> <br/>Now the short review without the poetic writing;-) Excellent lighting, mood, and capture - it is topnotch composition one that I can see on the front cover of a book on Poe or a playbill advertising the play.</td>', 'Upon my true face revealedFoolish Revelers fates are sealedSilent is my scream for I need no voiceGrave tidings  is the scarlet ''gift'' I foist Now the short review without the poetic writing;-) Excellent lighting, mood, and capture - it is topnotch composition one that I can see on the front cover of a book on Poe or a playbill advertising the play.', '2011-11-06 21:35:20.000000', NULL, 1),
(6586878, 982206, 131419, '<td valign="top">Really beautiful, you have captured such an atmosphere</td>', 'Really beautiful, you have captured such an atmosphere', '2011-11-06 21:38:35.000000', NULL, 1),
(6586879, 982238, 43463, '<td valign="top">A friend I came to comfort with story unfold<br/>At end, a terrible secret Roderick to me told<br/>Whitely, her wraith blew in to avenge with flare<br/>her touch ushers ruin as the shades on the wall declare.<br/> <br/>There is just something eerie about the shadows on the wall and the lady in white who stands alone. Knowing the story, the question becomes who exactly is the harbor of death in the composition: the white lady or the shadows on the wall who seem to be musicians whose musical sound may have the same power as the banshee''s cry.</td>', 'A friend I came to comfort with story unfoldAt end, a terrible secret Roderick to me toldWhitely, her wraith blew in to avenge with flareher touch ushers ruin as the shades on the wall declare. There is just something eerie about the shadows on the wall and the lady in white who stands alone. Knowing the story, the question becomes who exactly is the harbor of death in the composition: the white lady or the shadows on the wall who seem to be musicians whose musical sound may have the same power as the banshee''s cry.', '2011-11-06 21:39:33.000000', NULL, 1),
(6586880, 982203, 131419, '<td valign="top">Great shot, it looks so creepy, were you there by yourself?  very brave</td>', 'Great shot, it looks so creepy, were you there by yourself?  very brave', '2011-11-06 21:39:53.000000', NULL, 1),
