INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6592490, 981774, 30214, '<td valign="top">loved your image - so congrats on all the bling, well deserved! <br/> <br/>(and thanks for a nice comment on my entry... the dress was indeed not the best fit for the story, I''d prefer something very simple, but we went with what we had :))</td>', 'loved your image - so congrats on all the bling, well deserved!  (and thanks for a nice comment on my entry... the dress was indeed not the best fit for the story, I''d prefer something very simple, but we went with what we had :))', '2011-11-11 16:31:31.000000', NULL, 0),
(6592495, 981771, 92027, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Techo:</b></div><hr/><i> Sounds like shooting this was surreal. I didn''t vote but this was one of the few that stood out to me. I''ve been on the beach during those sand wiped days but never got a chance to capture it. Nice to know this was a single frame. May I ask how did you capture or add blueish tint to the ground? lens filter, color balance etc.? </i></td></tr></table> <br/>Thanks, and yes it''s pretty surreal to walk on this hot ground. This was shot late sunset/blue hour when all turnes blue, using a Lee filter to darken the sky agains ground, I did some curves, contrast and sharpen in lightroom. <br/><br/><i>Message edited by author 2011-11-11 16:42:40.</i></td>', 'Originally posted by Techo: Sounds like shooting this was surreal. I didn''t vote but this was one of the few that stood out to me. I''ve been on the beach during those sand wiped days but never got a chance to capture it. Nice to know this was a single frame. May I ask how did you capture or add blueish tint to the ground? lens filter, color balance etc.?  Thanks, and yes it''s pretty surreal to walk on this hot ground. This was shot late sunset/blue hour when all turnes blue, using a Lee filter to darken the sky agains ground, I did some curves, contrast and sharpen in lightroom. ', '2011-11-11 16:37:20.000000', '2011-11-11 16:42:40.000000', 0),
(6592530, 981573, 97225, '<td valign="top">Congratulations Judi. Fantastic in so many ways. About 1/4 of your voters (including me) gave you a 10! <br/><br/><i>Message edited by author 2011-11-11 17:27:35.</i></td>', 'Congratulations Judi. Fantastic in so many ways. About 1/4 of your voters (including me) gave you a 10! ', '2011-11-11 17:25:55.000000', '2011-11-11 17:27:35.000000', 0),
(6592532, 982191, 97225, '<td valign="top">Congratulations Christophe. A toss up between this and the winner which I couldn''t call. I gave you both 10.</td>', 'Congratulations Christophe. A toss up between this and the winner which I couldn''t call. I gave you both 10.', '2011-11-11 17:29:21.000000', NULL, 0),
(6592533, 982139, 97225, '<td valign="top">Congratulations! Great job.</td>', 'Congratulations! Great job.', '2011-11-11 17:30:39.000000', NULL, 0),
(6592586, 982145, 103142, '<td valign="top">So incredibly well done! Love the lighting and everything else! Huge congrats on the HM!<br/> <br/>(have you posted the 7+ and no bling icon yet? I need to go find it too, because of the pumpkin carving. Who would have thought? These were such high scoring challenges!!)<br/></td>', 'So incredibly well done! Love the lighting and everything else! Huge congrats on the HM! (have you posted the 7+ and no bling icon yet? I need to go find it too, because of the pumpkin carving. Who would have thought? These were such high scoring challenges!!)', '2011-11-11 18:28:03.000000', NULL, 0),
